import{_ as c,C as r,o as i,c as B,a5 as s,E as t,j as a,a as E,b as d,w as l,a6 as A}from"./chunks/framework.D_J2JZBr.js";const M=JSON.parse('{"title":"MEMS、传感与柔性电子","description":"从压电微系统到柔性传感，认识上科大的微纳机电与感知研究。","frontmatter":{"title":"MEMS、传感与柔性电子","description":"从压电微系统到柔性传感，认识上科大的微纳机电与感知研究。"},"headers":[],"relativePath":"explore-ic/research-directions/mems-sensors.md","filePath":"explore-ic/research-directions/mems-sensors.md","lastUpdated":1795531638000}'),m={name:"explore-ic/research-directions/mems-sensors.md"};function u(p,e,f,b,g,S){const n=r("FacultyList"),o=r("CourseTable"),h=r("Mermaid");return i(),B("div",null,[e[1]||(e[1]=s('<h1 id="mems、传感与柔性电子" tabindex="-1">MEMS、传感与柔性电子 <a class="header-anchor" href="#mems、传感与柔性电子" aria-label="Permalink to &quot;MEMS、传感与柔性电子&quot;">​</a></h1><h2 id="这个方向在做什么" tabindex="-1">这个方向在做什么 <a class="header-anchor" href="#这个方向在做什么" aria-label="Permalink to &quot;这个方向在做什么&quot;">​</a></h2><p>微机电系统（Micro-Electro-Mechanical Systems，MEMS）把机械结构、换能器与电子接口做到微小尺度；进一步缩小的结构常称 NEMS。传感研究关心如何把压力、加速度、磁场或生理变化变成可靠信号，柔性电子则探索器件和系统在弯曲、拉伸甚至贴附人体时如何工作。它们有交集，但并非所有传感器都是 MEMS，也并非所有柔性器件都用于穿戴。</p><p>核心研究问题包括：</p><ul><li>如何用压电、电容、电阻或磁电效应实现高效换能？</li><li>谐振频率、品质因数、灵敏度与带宽怎样相互制约？</li><li>温漂、应力、工艺偏差与封装如何改变器件特性？</li><li>柔性材料与刚性芯片之间怎样形成可靠互连？</li><li>弱信号读出、电源与数据处理如何和传感结构协同设计？</li></ul><h2 id="上科大谁在做" tabindex="-1">上科大谁在做 <a class="header-anchor" href="#上科大谁在做" aria-label="Permalink to &quot;上科大谁在做&quot;">​</a></h2><p>上科大的相关方向横跨微纳器件与传感系统。吴涛的 SMALL 实验室关注 MEMS/NEMS、压电器件与微系统；中心材料具体提到压电射频滤波器、超声换能器、磁电/声光传感器及脑机接口器件。曹文翰的公开方向包括柔性电子器件、软体机器人、太赫兹超表面器件与多层级微纳传感器件，体现了材料、结构和功能集成的交叉。</p><p>系统侧也有不同入口：梁俊睿研究环境能量收集、无源物联网、功率管理集成电路与机电一体化；叶朝锋关注电磁精密传感、电磁无损检测、弱磁测量和信号/图像处理。约 2024 年中心材料还介绍了任豪的 MEMS 谐振器、穿戴与植入式传感及微型能源器件；站内数据注明尚未检索到当前个人页，因此不能据此判断现阶段任职或招生状态。</p>',8)),t(n,{dir:"mems"}),e[2]||(e[2]=a("h2",{id:"相关上科大课程",tabindex:"-1"},[E("相关上科大课程 "),a("a",{class:"header-anchor",href:"#相关上科大课程","aria-label":'Permalink to "相关上科大课程"'},"​")],-1)),e[3]||(e[3]=a("p",null,"器件工艺、MEMS 设计与实验可以相互配合，柔性电子另有专门课程；具体实验条件和选课要求以课程公布为准。",-1)),t(o,{codes:"EE111,EE224A,EE224B,EE224J,EE224G,EE229"}),e[4]||(e[4]=a("h2",{id:"知识前置",tabindex:"-1"},[E("知识前置 "),a("a",{class:"header-anchor",href:"#知识前置","aria-label":'Permalink to "知识前置"'},"​")],-1)),e[5]||(e[5]=a("p",null,"下图组织概念上的学习顺序，不代表正式先修要求；材料力学、振动与多物理场基础可按课题补充。",-1)),(i(),d(A,null,{default:l(()=>[t(h,{id:"mermaid-64",class:"mermaid",graph:"graph%20LR%0A%20%20A%5B%22%E6%99%AE%E9%80%9A%E7%89%A9%E7%90%86%E4%B8%8E%E5%BE%AE%E7%A7%AF%E5%88%86%22%5D%20--%3E%20B%5B%22EE111%20%E7%94%B5%E8%B7%AF%E5%9F%BA%E7%A1%80%22%5D%0A%20%20A%20--%3E%20C%5B%22%E5%8A%9B%E5%AD%A6%E4%B8%8E%E6%9D%90%E6%96%99%E5%9F%BA%E7%A1%80%22%5D%0A%20%20A%20--%3E%20D%5B%22EE224A%20%E5%BE%AE%E7%BA%B3%E5%99%A8%E4%BB%B6%E5%B7%A5%E8%89%BA%E5%9F%BA%E7%A1%80%22%5D%0A%20%20B%20--%3E%20E%5B%22EE224B%20%E5%BE%AE%E7%BA%B3%E6%9C%BA%E7%94%B5%E7%B3%BB%E7%BB%9F%E5%9F%BA%E7%A1%80%22%5D%0A%20%20C%20--%3E%20E%0A%20%20E%20--%3E%20F%5B%22EE224J%20%E5%BE%AE%E7%BA%B3%E6%9C%BA%E7%94%B5%E7%B3%BB%E7%BB%9F%E5%AE%9E%E9%AA%8C%22%5D%0A%20%20E%20--%3E%20G%5B%22EE224G%20%E5%BE%AE%E6%9C%BA%E7%94%B5%E7%B3%BB%E7%BB%9F%E8%AE%BE%E8%AE%A1%E8%BF%9B%E9%98%B6%E4%B8%8E%E5%AE%9E%E8%B7%B5%22%5D%0A%20%20B%20--%3E%20H%5B%22EE115A%20%E6%A8%A1%E6%8B%9F%E7%94%B5%E8%B7%AF%22%5D%0A%20%20C%20--%3E%20I%5B%22EE229%20%E6%9F%94%E6%80%A7%E7%94%B5%E5%AD%90%E5%AD%A6%22%5D%0A%20%20F%20--%3E%20J%5B%22%E4%BC%A0%E6%84%9F%E5%99%A8%E4%B8%8E%E5%BE%AE%E7%B3%BB%E7%BB%9F%E7%A0%94%E7%A9%B6%22%5D%0A%20%20G%20--%3E%20J%0A%20%20H%20--%3E%20J%0A%20%20I%20--%3E%20J%0A%20%20D%20--%3E%20J%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=s('<h2 id="领域地图" tabindex="-1">领域地图 <a class="header-anchor" href="#领域地图" aria-label="Permalink to &quot;领域地图&quot;">​</a></h2><ul><li><strong>研究机构</strong>：Berkeley、MIT、清华和中科院上海微系统所都有微系统相关研究；柔性电子可关注 Northwestern 等机构的相关团队。检索时应按换能机制与应用场景细分。</li><li><strong>产业参照</strong>：Bosch、STMicroelectronics 的 MEMS 传感器，TDK 的传感与声学器件，适合观察封装、可靠性和量产规格如何约束设计；不表示本校合作关系。</li><li><strong>会议与期刊</strong>：IEEE MEMS、TRANSDUCERS、IEEE SENSORS；Journal of Microelectromechanical Systems（JMEMS）、Microsystems &amp; Nanoengineering、Sensors and Actuators 系列。</li></ul><p>读传感论文时，不应只比较最高灵敏度。测量范围、噪声谱、检测限、响应时间、迟滞和温度条件共同决定器件能否使用；人体相关应用还涉及伦理审批与生物兼容性要求。</p><h2 id="入门资源" tabindex="-1">入门资源 <a class="header-anchor" href="#入门资源" aria-label="Permalink to &quot;入门资源&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/devices-and-process/resources">器件自学</a>：理解工艺、器件和材料基础。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/analog-ic/resources">模拟自学</a>：学习放大、滤波、噪声和传感读出接口。</li><li><a href="https://nanohub.org/" target="_blank" rel="noreferrer">nanoHUB</a>：查找微纳器件教学与仿真材料。</li><li><a href="https://ieee-sensors.org/" target="_blank" rel="noreferrer">IEEE Sensors Council</a>：了解传感领域会议与教育入口。</li></ul><p>建议先针对一种传感器写清“被测量—换能机制—读出量—校准方法”四项，再复现公开模型。涉及微纳加工、高压、激光或人体实验时，应在授权场地和指导下开展。</p><h2 id="社区经验征集" tabindex="-1">社区经验征集 <a class="header-anchor" href="#社区经验征集" aria-label="Permalink to &quot;社区经验征集&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎该方向课题组同学通过 <a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a> 补充“组里在做什么”、公开仿真与测量训练路径，以及进组前的基础准备；设备使用条件请引用正式规定。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/wutao/main.htm" target="_blank" rel="noreferrer">吴涛学院主页</a>、<a href="https://small.shanghaitech.edu.cn/" target="_blank" rel="noreferrer">SMALL</a>、<a href="https://sist.shanghaitech.edu.cn/cwh/main.htm" target="_blank" rel="noreferrer">曹文翰学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/liangjr/main.htm" target="_blank" rel="noreferrer">梁俊睿学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/yechf/main.htm" target="_blank" rel="noreferrer">叶朝锋学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/_upload/article/files/d0/82/218152ad4bd29c54d8a89d0e6be7/2cba84cd-d335-4a72-8f17-68175bed8e69.pdf" target="_blank" rel="noreferrer">后摩尔中心介绍材料</a>：任豪相关内容为约 2024 年历史材料，当前信息以学院为准。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年 SIST 开课计划</a>。</li></ul>',10))])}const k=c(m,[["render",u]]);export{M as __pageData,k as default};
